-- PartyHub: 100 new unique question prompts in each of 10 categories (IDs 101-1100).
-- Safe to rerun: upserts rows by ID. Existing question IDs 1-100 are preserved.
on conflict (id) do update set category=excluded.category,difficulty=excluded.difficulty,prompt=excluded.prompt,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation,active=true;

-- Verify active question count by category. Each category should have at least 100 new entries.
select category, count(*) filter (where active) as active_questions from public.questions group by category order by category;